// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, interpolateColors } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type LineGraphDropProps = Record<string, any>;

const LineGraphDrop: React.FC<LineGraphDropProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = false,
  durationInSeconds = 5,
  startLineColor = "#22c55e",
  startFillColor = "#22c55e",
  lineColor = "#ef4444",
  fillColor = "#ef4444",
  gridColor = "#27272a",
  textColor = "#f4f4f5",
  title = "System Reliability",
  titleFontFamily = "SpaceGrotesk",
  labelFontFamily = "Inter",
  startValue = 100,
  endValue = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle parsing safety for colors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const fontMap: Record<string, string> = {
    Inter: interFamily,
    SpaceGrotesk: spaceGroteskFamily,
  };
  const activeTitleFont = fontMap[titleFontFamily] || interFamily;
  const activeLabelFont = fontMap[labelFontFamily] || interFamily;

  // Chart Dimensions
  const startX = width * 0.15;
  const endX = width * 0.85;
  const startY = height * 0.8; // Bottom of chart (0%)
  const endY = height * 0.3; // Top of chart (100%)

  // Animation Timing
  const totalFrames = Math.round(durationInSeconds * fps);
  const startFrame = 15;
  const endFrame = totalFrames - 30; // Pause at end

  // Progress of the line drawing (0 to 1)
  const p = interpolate(frame, [startFrame, endFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const crashStart = 0.25;
  const crashEnd = 0.55;

  // Value function: Starts flat, crashes, then stays flat
  const getVal = (t: number) => {
    if (t <= crashStart) return startValue;
    if (t >= crashEnd) return endValue;
    // Cubic smoothstep for the drop
    const norm = (t - crashStart) / (crashEnd - crashStart);
    const ease = 3 * norm * norm - 2 * norm * norm * norm;
    return startValue - (startValue - endValue) * ease;
  };

  // Build the path deterministically
  const pts = [];
  const resolution = 400;
  for (let i = 0; i <= resolution; i++) {
    const stepP = i / resolution;
    if (stepP > p) break;
    const val = getVal(stepP);
    const x = startX + stepP * (endX - startX);
    const y = endY + ((100 - val) / 100) * (startY - endY);
    pts.push({ x, y });
  }

  // Ensure leading edge is precisely placed
  let currentVal = startValue;
  let currentX = startX;
  let currentY = endY + ((100 - startValue) / 100) * (startY - endY);

  if (p > 0) {
    currentVal = getVal(p);
    currentX = startX + p * (endX - startX);
    currentY = endY + ((100 - currentVal) / 100) * (startY - endY);
    pts.push({ x: currentX, y: currentY });
  }

  const pathData = pts.length > 0 
    ? `M ${pts[0].x} ${pts[0].y} ` + pts.slice(1).map(pt => `L ${pt.x} ${pt.y}`).join(" ")
    : "";

  const fillData = pts.length > 0
    ? pathData + ` L ${currentX} ${startY} L ${startX} ${startY} Z`
    : "";

  // Camera Animation Math
  // The zoom starts tight at 4x and zooms out to 1x exactly during the crash
  const zoomEaseRaw = Math.max(0, Math.min(1, (p - 0.2) / 0.45));
  const zoomEase = Easing.inOut(Easing.cubic)(zoomEaseRaw);
  const zoom = interpolate(zoomEase, [0, 1], [4, 1]);

  // We want the camera to focus slightly ahead of the dot when zoomed in
  // Screen center is width / 2 (960)
  const camX = interpolate(zoomEase, [0, 1], [currentX + 100 / zoom, width / 2]);
  const camY = interpolate(zoomEase, [0, 1], [currentY, height / 2]);

  // Translate coordinates to center the camera target
  const translateX = width / 2 - camX;
  const translateY = height / 2 - camY;

  // Determine the current color for the leading dot based on progress
  const currentLineColor = interpolateColors(
    p,
    [crashStart, crashEnd],
    [startLineColor, lineColor]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      {/* 
        The core wrapper applies the inverse camera transformation.
        By applying translate then scale (via CSS order), we frame the exact coordinate. 
      */}
      <AbsoluteFill
        style={{
          transformOrigin: "center center",
          transform: `scale(${zoom}) translate(${translateX}px, ${translateY}px)`,
          transition: "none",
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ overflow: "visible" }}
        >
          <defs>
            {/* Horizontal gradient mapping the crash range across the exact X coordinates */}
            <linearGradient id="lineGrad" x1={startX} y1={0} x2={endX} y2={0} gradientUnits="userSpaceOnUse">
              <stop offset="25%" stopColor={startLineColor} />
              <stop offset="55%" stopColor={lineColor} />
              <stop offset="100%" stopColor={lineColor} />
            </linearGradient>

            {/* Same horizontal coordinate mapping for the filled area color */}
            <linearGradient id="fillGradX" x1={startX} y1={0} x2={endX} y2={0} gradientUnits="userSpaceOnUse">
              <stop offset="25%" stopColor={startFillColor} />
              <stop offset="55%" stopColor={fillColor} />
              <stop offset="100%" stopColor={fillColor} />
            </linearGradient>

            {/* Vertical opacity fade used as a mask for the filled area */}
            <linearGradient id="fillGradY" x1="0" y1={endY} x2="0" y2={startY} gradientUnits="userSpaceOnUse">
              <stop offset="0%" stopColor="white" stopOpacity={0.4} />
              <stop offset="100%" stopColor="white" stopOpacity={0.0} />
            </linearGradient>
            
            <mask id="fadeMask">
              <rect x={0} y={0} width={width} height={height} fill="url(#fillGradY)" />
            </mask>

            <filter id="glow">
              <feGaussianBlur stdDeviation="6" result="coloredBlur" />
              <feMerge>
                <feMergeNode in="coloredBlur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>

          {/* Grid Lines & Y-Axis Labels */}
          {[0, 20, 40, 60, 80, 100].map((val) => {
            const y = endY + ((100 - val) / 100) * (startY - endY);
            return (
              <g key={val}>
                <line
                  x1={startX}
                  y1={y}
                  x2={endX}
                  y2={y}
                  stroke={gridColor}
                  strokeWidth={2}
                  strokeDasharray="8 8"
                  opacity={0.6}
                />
                <text
                  x={startX - 30}
                  y={y + 6}
                  fill={textColor}
                  fontSize={18}
                  fontFamily={activeLabelFont}
                  textAnchor="end"
                  opacity={0.8}
                >
                  {val}%
                </text>
              </g>
            );
          })}

          {/* Filled Area */}
          {fillData && (
            <path 
              d={fillData} 
              fill="url(#fillGradX)" 
              mask="url(#fadeMask)" 
              style={{ transition: "none" }} 
            />
          )}

          {/* Line Path */}
          {pathData && (
            <path
              d={pathData}
              fill="none"
              stroke="url(#lineGrad)"
              strokeWidth={3}
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{ filter: "url(#glow)", transition: "none" }}
            />
          )}

          {/* Leading Dot - Inverse scaled so it remains constant size visually */}
          <circle
            cx={currentX}
            cy={currentY}
            r={8 / zoom}
            fill={backgroundColor}
            stroke={currentLineColor}
            strokeWidth={4 / zoom}
            style={{ filter: "url(#glow)", transition: "none" }}
          />
        </svg>

        {/* Global Title */}
        <div
          style={{
            position: "absolute",
            left: startX,
            top: endY - 120,
            display: "flex",
            flexDirection: "column",
            transition: "none",
          }}
        >
          <span
            style={{
              color: textColor,
              fontFamily: activeTitleFont,
              fontSize: 48,
              fontWeight: 700,
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            {title}
          </span>
        </div>

        {/* Current Value Label Attached to Dot */}
        {/* We use inverse scaling here so the label is always perfectly legible regardless of camera zoom */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            transformOrigin: "bottom center",
            transform: `translate(${currentX}px, ${currentY - 30}px) scale(${1 / zoom}) translate(-50%, -100%)`,
            transition: "none",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
          <div
            style={{
              backgroundColor: textColor,
              color: backgroundColor,
              fontFamily: activeLabelFont,
              fontSize: 24,
              fontWeight: 700,
              padding: "8px 16px",
              borderRadius: 8,
              boxShadow: "0 8px 16px rgba(0,0,0,0.5)",
              transition: "none",
            }}
          >
            {currentVal.toFixed(1)}%
          </div>
          {/* Tooltip triangle */}
          <div
            style={{
              width: 0,
              height: 0,
              borderLeft: "8px solid transparent",
              borderRight: "8px solid transparent",
              borderTop: `8px solid ${textColor}`,
              transition: "none",
            }}
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default LineGraphDrop;